function petshop_get_invoice_document_type( $order ) {
    if ( ! $order instanceof WC_Order ) return 'invoice';
    // S1662 (Raimio taisyklė 2026-09-09): PVM sąskaita (AVPN) — TIK apmokėtiems.
    // Kol neapmokėta (bet kuris mokėjimo būdas) — išankstinė (IAPV).
    // Anksčiau proforma buvo tik bacs pending/on-hold — Paysera pending degino AVPN numerius.
    if ( $order->is_paid() ) {
        return 'invoice';
    }
    if ( in_array( $order->get_status(), array( 'pending', 'on-hold', 'failed', 'checkout-draft' ), true ) ) {
        return 'proforma';
    }
    // cancelled/refunded be apmokėjimo — sąskaitos nekuriam, bet jei kas pareikalaus, NEdeginam AVPN
    if ( in_array( $order->get_status(), array( 'cancelled', 'refunded' ), true ) && ! $order->get_date_paid() ) {
        return 'proforma';
    }
    return 'invoice';
}

